-- Local integration examples only; not real admissions data or past examination questions.
-- Demo logins: student / student2. Supply @student_password_hash and @student2_password_hash
-- in this MySQL session before running this file (BCrypt cost 12; no default credentials).
-- Run after 01_schema.mysql.sql. Existing IDs and accounts are not overwritten.
SET NAMES utf8mb4;
USE `kaoyan_ai`;
-- Validate both externally supplied hashes before inserting any demo data.
CREATE TEMPORARY TABLE `_demo_password_check` (
  `password_hash` varchar(100) NOT NULL,
  CHECK (CHAR_LENGTH(`password_hash`) = 60 AND LEFT(`password_hash`, 7) IN ('$2a$12$', '$2b$12$', '$2y$12$'))
);
DROP TEMPORARY TABLE `_demo_password_check`;
START TRANSACTION;
COMMIT;
